        state.put("executions",f.j.queryForList("SELECT * FROM external_execution WHERE task_id=? LIMIT 2",task).stream().map(Task11B2PipelineIT::strings).toList());
        state.put("attempts",f.j.queryForList("SELECT * FROM task_attempt WHERE task_id=? ORDER BY attempt LIMIT 2",task).stream().map(Task11B2PipelineIT::strings).toList());
        state.put("reservations",f.j.queryForList("SELECT r.* FROM model_reservation r JOIN external_execution e ON e.id=r.execution_id WHERE e.task_id=? LIMIT 2",task).stream().map(Task11B2PipelineIT::strings).toList());
